const Database = require("better-sqlite3");

const db = new Database("/tmp/airports.db");

db.exec(`
  CREATE TABLE IF NOT EXISTS airports (
    id INTEGER PRIMARY KEY,
    name TEXT,
    latitude_deg REAL,
    longitude_deg REAL,
    iso_country TEXT,
    municipality TEXT,
    iata_code TEXT
  )
`);

const rowCount = db.prepare("SELECT COUNT(*) AS count FROM airports").get().count;

if (rowCount === 0) {
  const airports = require("./airports.json");

  const insertStatement = db.prepare(`
    INSERT INTO airports (
      id, name, latitude_deg, longitude_deg, iso_country, municipality, iata_code
    )
    VALUES (?, ?, ?, ?, ?, ?, ?)
  `);

  const insertTransaction = db.transaction((rows) => {
    for (const row of rows) {
      insertStatement.run(
        row.id,
        row.name,
        row.latitude_deg,
        row.longitude_deg,
        row.iso_country,
        row.municipality,
        row.iata_code
      );
    }
  });

  insertTransaction(airports);
}

module.exports = db;

const express = require("express");

const app = express();
const PORT = 3000;

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

