const express = require("express");
const { getRandomAirport } = require("./database");

const app = express();
const PORT = 3000;

app.get("/api/random-airport", (req, res) => {
  try {
    const airport = getRandomAirport();

    res.status(200).json({ airport: airport });
  } catch (error) {
    res
      .status(500)
      .json({ message: "Error fetching airports", error: error.message });
  }
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});

